<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';admin_require_login();if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf_check();$id=(int)($_POST['id']??0);$qty=filter_var($_POST['stock_quantity']??null,FILTER_VALIDATE_INT);if($id>0&&$qty!==false&&$qty>=0){$s=$pdo->prepare('UPDATE products SET stock_quantity=? WHERE id=?');$s->execute([$qty,$id]);$_SESSION['flash']='Stock quantity updated.';}else $_SESSION['flash']='Enter a valid stock quantity.';redirect('inventory.php');}$q=trim((string)($_GET['q']??''));$sql='SELECT id,name,sku,stock_quantity,low_stock_threshold,is_active FROM products';$params=[];if($q!==''){$sql.=' WHERE name LIKE ? OR sku LIKE ?';$params=['%'.$q.'%','%'.$q.'%'];}$sql.=' ORDER BY (stock_quantity<=low_stock_threshold) DESC,name LIMIT 300';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$low=count(array_filter($rows,fn($r)=>(int)$r['stock_quantity']<=(int)$r['low_stock_threshold']));admin_page_start('Inventory');?><div class="row g-3 mb-3"><div class="col-md-4"><div class="panel"><div class="text-secondary">Products listed</div><div class="h3 mb-0"><?=count($rows)?></div></div></div><div class="col-md-4"><div class="panel"><div class="text-secondary">Low stock / reorder alert</div><div class="h3 mb-0"><?=$low?></div></div></div></div><div class="panel"><form class="d-flex gap-2 mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search product or SKU"><button class="btn btn-outline-secondary">Search</button></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>SKU</th><th>Stock</th><th>Threshold</th><th>Update stock</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><?php if(!(int)$r['is_active']):?> <span class="badge text-bg-secondary">Hidden</span><?php endif;?></td><td><?=e($r['sku'])?></td><td><span class="badge <?=((int)$r['stock_quantity']<=(int)$r['low_stock_threshold'])?'text-bg-warning':'text-bg-success'?>"><?= (int)$r['stock_quantity']?></span></td><td><?= (int)$r['low_stock_threshold']?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input class="form-control" style="max-width:120px" type="number" min="0" name="stock_quantity" value="<?=(int)$r['stock_quantity']?>" required><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_page_end();?>